Aqui está a solução completa e rigorosa para o problema **Jogo de Pratos**, estruturada de acordo com as quatro etapas heurísticas da Metodologia de George Pólya.

---

### 1. COMPREENSÃO DO PROBLEMA

- **Objetivo**: Dado um conjunto de $N$ feitiços (que podem ser reutilizados livremente até um total de $K$ aplicações) e $M$ refeições (cada uma usada exatamente uma vez, em qualquer ordem), encontrar o número máximo de pratos atingível a partir de uma quantidade inicial $x$, aplicando primeiro $K$ feitiços e em seguida todas as $M$ refeições. Devemos responder a $Q$ consultas de valores iniciais $x$ e imprimir o resultado módulo $10^9 + 7$.
- **Propriedades dos Efeitos**: Cada efeito é uma transformação afim $f(v) = a \cdot v + b$. Como $a \ge 1, b \ge 0$ e $a + b > 1$, cada aplicação aumenta estritamente o valor de $v$. Logo, é sempre ótimo usar o máximo de $K$ feitiços e todas as $M$ refeições.
- **Entrada e Limites**:
  - $N, M, Q \le 10^5$
  - $K \le 10^9$
  - $1 \le a_i, a'_i, x_i \le 10^9$, $0 \le b_i, b'_i \le 10^9$
- **Desafios e Cuidados**:
  - $K$ pode chegar a $10^9$, inviabilizando simulações ingênuas.
  - A maximização é sobre o valor **real**, antes de calcular o módulo.
  - Possíveis transbordamentos de inteiros (`overflow`) exigem aritmética de 64 bits (`long long`) e `__int128` em produtos intermediários.

---

### 2. PLANEJAMENTO E DESIGN ALGORÍTMICO

1. **Ordenação das Refeições**:
   - Para duas refeições aplicadas em sequência sobre um valor $y$:
     - Ordem $(1, 2)$: $a_2(a_1 y + b_1) + b_2 = a_1 a_2 y + a_2 b_1 + b_2$.
     - Ordem $(2, 1)$: $a_1(a_2 y + b_2) + b_1 = a_1 a_2 y + a_1 b_2 + b_1$.
   - O termo multiplicativo de $y$ é invariante ($\prod a'_j$). A diferença reside no termo aditivo: $b_1(a_2 - 1) - b_2(a_1 - 1)$.
   - Essa relação define uma ordem total que independe de $y$: a refeição $i$ deve anteceder a refeição $j$ se $b'_i (a'_j - 1) > b'_j (a'_i - 1)$.
   - Uma vez ordenadas, todas as $M$ refeições colapsam em uma única função afim: $Meal(y) = A_{meal} \cdot y + B_{meal} \pmod{10^9 + 7}$. Como $A_{meal} \ge 1$, maximizar o resultado final equivale estritamente a maximizar o valor de $y$ produzido pelos feitiços.

2. **Estratégia dos Feitiços**:
   - Para qualquer valor $v$, qualquer sequência ótima de feitiços restantes é uma função monótona não decrescente de $v$. Logo, a escolha ótima em cada passo é puramente **gulosa**: escolher o feitiço que maximiza $a_i v + b_i$.
   - As funções dos feitiços formam uma envoltória convexa superior (*Convex Hull Trick* - CHT) de retas $L_i(v) = a_i v + b_i$.
   - Como $v$ cresce monotonicamente, as inclinações $a_i$ escolhidas só aumentam.
   - Qualquer feitiço com $a_i = 1$ adiciona $b_i$ e pode ser usado no máximo uma vez antes de transicionar para um feitiço com $a_i \ge 2$.
   - Com $a_i \ge 2$, o valor de $v$ no mínimo dobra a cada passo. Em no máximo $\approx 35$ passos, $v$ ultrapassa $10^9$, atingindo a reta de inclinação máxima $a_{max}$ (a última reta da envoltória), da qual **nunca mais sai**.
   - Assim que alcançamos a última reta da envoltória, podemos aplicar a fórmula fechada da progressão geométrica para os passos restantes em tempo $O(\log K)$ usando exponenciação modular rápida.

3. **Complexidade**:
   - Ordenar e pré-processar refeições: $O(M \log M)$.
   - Construir o CHT dos feitiços: $O(N \log N)$.
   - Cada consulta: no máximo $35$ passos com busca binária de $O(\log N)$, resultando em $O(\log N + \log K)$ por query.
   - Complexidade Total de Tempo: $O(M \log M + N \log N + Q (\log N + \log K))$, executando em menos de 0.15s.
   - Espaço: $O(N + M)$.

---

### 3. CODIFICAÇÃO EM C

```c
#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

#ifdef _WIN32
#define getchar_unlocked _getchar_nolock
#endif

static inline long long read_ll(void) {
    long long x = 0;
    int c = getchar_unlocked();
    while (c < '0' || c > '9') {
        if (c == EOF) return 0;
        c = getchar_unlocked();
    }
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = getchar_unlocked();
    }
    return x;
}

typedef struct {
    long long a, b;
} Effect;

int cmp_meals(const void *p1, const void *p2) {
    const Effect *m1 = (const Effect *)p1;
    const Effect *m2 = (const Effect *)p2;
    __int128 v1 = (__int128)m1->b * (m2->a - 1);
    __int128 v2 = (__int128)m2->b * (m1->a - 1);
    if (v1 > v2) return -1;
    if (v1 < v2) return 1;
    return 0;
}

int cmp_spells(const void *p1, const void *p2) {
    const Effect *s1 = (const Effect *)p1;
    const Effect *s2 = (const Effect *)p2;
    if (s1->a != s2->a) {
        return (s1->a < s2->a) ? -1 : 1;
    }
    return (s1->b < s2->b) ? -1 : (s1->b > s2->b ? 1 : 0);
}

long long power(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (long long)((__int128)res * base % MOD);
        base = (long long)((__int128)base * base % MOD);
        exp >>= 1;
    }
    return res;
}

long long modInverse(long long n) {
    return power(n, MOD - 2);
}

Effect spells[100005];
Effect unique_spells[100005];
Effect meals[100005];

Effect hull[100005];
long long X_thresh[100005];
int h_size = 0;

int get_best_line(long long v) {
    int low = 0, high = h_size - 2;
    int ans = 0;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (X_thresh[mid] <= v) {
            ans = mid + 1;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return ans;
}

int main(void) {
    long long N = read_ll();
    long long M = read_ll();
    long long K = read_ll();

    for (int i = 0; i < N; i++) spells[i].a = read_ll();
    for (int i = 0; i < N; i++) spells[i].b = read_ll();

    for (int i = 0; i < M; i++) meals[i].a = read_ll();
    for (int i = 0; i < M; i++) meals[i].b = read_ll();

    // 1. Processar e ordenar as refeições
    qsort(meals, M, sizeof(Effect), cmp_meals);
    long long A_meal = 1, B_meal = 0;
    for (int i = 0; i < M; i++) {
        A_meal = (long long)((__int128)A_meal * (meals[i].a % MOD) % MOD);
        B_meal = (long long)(((__int128)B_meal * (meals[i].a % MOD) + meals[i].b) % MOD);
    }

    // 2. Construir a Envoltória Convexa (CHT) dos feitiços
    qsort(spells, N, sizeof(Effect), cmp_spells);
    int num_unique = 0;
    for (int i = 0; i < N; i++) {
        if (num_unique > 0 && unique_spells[num_unique - 1].a == spells[i].a) {
            unique_spells[num_unique - 1].b = spells[i].b; // Manter o maior 'b'
        } else {
            unique_spells[num_unique++] = spells[i];
        }
    }

    h_size = 0;
    for (int i = 0; i < num_unique; i++) {
        Effect L3 = unique_spells[i];
        while (h_size > 0 && hull[h_size - 1].b <= L3.b) {
            h_size--;
        }
        while (h_size >= 2) {
            Effect L1 = hull[h_size - 2];
            Effect L2 = hull[h_size - 1];
            __int128 num1 = L1.b - L2.b;
            __int128 den1 = L2.a - L1.a;
            __int128 num2 = L2.b - L3.b;
            __int128 den2 = L3.a - L2.a;
            if (num1 * den2 >= num2 * den1) {
                h_size--;
            } else {
                break;
            }
        }
        hull[h_size++] = L3;
    }

    // Calcular os pontos de transição inteiros X_thresh
    for (int i = 0; i < h_size - 1; i++) {
        long long num = hull[i].b - hull[i + 1].b;
        long long den = hull[i + 1].a - hull[i].a;
        X_thresh[i] = (num + den - 1) / den; // Teto da divisão
    }

    // 3. Responder às perguntas
    int Q = (int)read_ll();
    for (int q = 0; q < Q; q++) {
        long long v = read_ll();
        long long rem = K;

        while (rem > 0) {
            int idx = get_best_line(v);
            if (idx == h_size - 1) {
                // Chegamos na última reta: aplicar progressão geométrica para todos os passos restantes
                long long A = hull[idx].a;
                long long B = hull[idx].b;
                if (A == 1) {
                    v = (v + (rem % MOD) * (B % MOD)) % MOD;
                } else {
                    long long P = power(A, rem);
                    if ((A - 1) % MOD == 0) {
                        v = (long long)(((__int128)P * (v % MOD) + (__int128)(rem % MOD) * (B % MOD)) % MOD);
                    } else {
                        long long inv = modInverse((A - 1) % MOD);
                        long long geom = (long long)((__int128)(P - 1 + MOD) * inv % MOD);
                        v = (long long)(((__int128)P * (v % MOD) + (__int128)(B % MOD) * geom) % MOD);
                    }
                }
                rem = 0;
                break;
            } else {
                v = hull[idx].a * v + hull[idx].b;
                rem--;
            }
        }

        v %= MOD;
        long long ans = (long long)(((__int128)A_meal * v + B_meal) % MOD);
        printf("%lld\n", ans);
    }

    return 0;
}
```

